1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strconv"
10		"unicode/utf8"
11	)
12	
13	// EvalReason is the machine-readable outcome of a flag evaluation.
14	type EvalReason string
15	
16	const (
17		EvalDisabled EvalReason = "disabled"
18		EvalRule     EvalReason = "rule"
19		EvalDefault  EvalReason = "default"
20	)
21	
22	// Condition is one predicate over an evaluation context.
23	type Condition struct {
24		Attribute string
25		Op        string
26		// strVal 用于 eq；inVal 用于 in（至少一项）。
27		strVal string
28		inVal  []string
29	}
30	
31	// Rule groups conditions that must all hold; on match the flag takes Value.
32	type Rule struct {
33		ID         string
34		Value      bool
35		Conditions []Condition
36	}
37	
38	// Flag is one feature toggle with its default and ordered rules.
39	type Flag struct {
40		Key     string
41		Enabled bool
42		Default bool
43		Rules   []Rule
44	}
45	
46	// Config is a validated feature flag configuration.
47	type Config struct {
48		Flags []Flag
49	}
50	
51	// EvalResult is the deterministic outcome of evaluating one flag.
52	type EvalResult struct {
53		Key    string     `json:"key"`
54		Value  bool       `json:"value"`
55		Reason EvalReason `json:"reason"`
56		RuleID *string    `json:"ruleId"`
57	}
58	
59	// Equals reports whether two evaluation results are identical.
60	func (r EvalResult) Equals(other EvalResult) bool {
61		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
62			return false
63		}
64		if (r.RuleID == nil) != (other.RuleID == nil) {
65			return false
66		}
67		if r.RuleID != nil && *r.RuleID != *other.RuleID {
68			return false
69		}
70		return true
71	}
72	
73	// Context is a validated map of attribute names to string values.
74	type Context struct {
75		values map[string]string
76	}
77	
78	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
79	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
80	func LoadConfig(path string) (*Config, error) {
81		raw, err := os.ReadFile(path)
82		if err != nil {
83			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
84		}
85		return ParseConfig(raw)
86	}
87	
88	// LoadContext reads and validates a UTF-8 JSON context file.
89	func LoadContext(path string) (*Context, error) {
90		raw, err := os.ReadFile(path)
91		if err != nil {
92			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
93		}
94		return ParseContext(raw)
95	}
96	
97	// unmarshalStrictJSON 严格解码一个 UTF-8 JSON 文档到 any，并保持与
98	// json.Unmarshal 相同的单文档语义：文档之后只允许空白，不允许第二个值。
99	// 使用 json.Decoder + UseNumber：数字按原文保留为 json.Number，而不是强制
100	// 转成 float64——语法合法但超出浮点范围的数字（如 1e400、由 1 后接 400 个 0
101	// 组成的整数）不应被当成“JSON 无效”，它们是合法的 JSON 数字，由后续的值
102	// 类型检查以所属字段的类型错误报告。
103	func unmarshalStrictJSON(raw []byte) (any, error) {
104		dec := json.NewDecoder(bytes.NewReader(raw))
105		dec.UseNumber()
106		var doc any
107		if err := dec.Decode(&doc); err != nil {
108			return nil, err
109		}
110		// Decoder 本身容忍文档之后的额外 JSON 值，需显式补回 Unmarshal 的严格性。
111		offset := int(dec.InputOffset())
112		var extra any
113		if err := dec.Decode(&extra); err != io.EOF {
114			if err != nil {
115				return nil, err
116			}
117			for offset < len(raw) && isJSONWhitespace(raw[offset]) {
118				offset++
119			}
120			c := byte(0)
121			if offset < len(raw) {
122				c = raw[offset]
123			}
124			return nil, fmt.Errorf("invalid character %q after top-level value", c)
125		}
126		return doc, nil
127	}
128	
129	// isJSONWhitespace 报告 b 是否为 JSON 允许的空白字节。
130	func isJSONWhitespace(b byte) bool {
131		return b == ' ' || b == '\t' || b == '\n' || b == '\r'
132	}
133	
134	// ParseConfig parses a config document from JSON bytes with strict typing.
135	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
136	func ParseConfig(raw []byte) (*Config, error) {
137		if !utf8.Valid(raw) {
138			return nil, fmt.Errorf("config: file is not valid UTF-8")
139		}
140		if err := rejectInvalidUnicodeEscapes(raw, "config"); err != nil {
141			return nil, err
142		}
143		if err := rejectDuplicateFields(raw, "config"); err != nil {
144			return nil, err
145		}
146		doc, err := unmarshalStrictJSON(raw)
147		if err != nil {
148			return nil, fmt.Errorf("config: invalid JSON: %w", err)
149		}
150		root, ok := doc.(map[string]any)
151		if !ok {
152			return nil, fmt.Errorf("config: top level must be a JSON object")
153		}
154		flagsRaw, present := root["flags"]
155		if !present {
156			return nil, fmt.Errorf("config.flags: field is required")
157		}
158		if flagsRaw == nil {
159			return nil, fmt.Errorf("config.flags: must be an array, got null")
160		}
161		flagsArr, ok := flagsRaw.([]any)
162		if !ok {
163			return nil, fmt.Errorf("config.flags: must be an array")
164		}
165		cfg := &Config{}
166		seenKeys := map[string]int{}
167		for i, fr := range flagsArr {
168			flag, err := parseFlag(fr, i)
169			if err != nil {
170				return nil, err
171			}
172			if prev, dup := seenKeys[flag.Key]; dup {
173				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
174			}
175			seenKeys[flag.Key] = i
176			cfg.Flags = append(cfg.Flags, flag)
177		}
178		return cfg, nil
179	}
180	
181	// ParseContext parses an attribute-name -> string context object; it may be empty.
182	func ParseContext(raw []byte) (*Context, error) {
183		if !utf8.Valid(raw) {
184			return nil, fmt.Errorf("context: file is not valid UTF-8")
185		}
186		if err := rejectInvalidUnicodeEscapes(raw, "context"); err != nil {
187			return nil, err
188		}
189		if err := rejectDuplicateFields(raw, "context"); err != nil {
190			return nil, err
191		}
192		doc, err := unmarshalStrictJSON(raw)
193		if err != nil {
194			return nil, fmt.Errorf("context: invalid JSON: %w", err)
195		}
196		root, ok := doc.(map[string]any)
197		if !ok {
198			return nil, fmt.Errorf("context: top level must be a JSON object")
199		}
200		// 值类型必须按原文顺序逐个判定：Go map 的遍历顺序不稳定，不能直接
201		// range root，否则同一文件在不同运行中可能报告不同属性。对象或数组
202		// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
203		if err := checkContextValueTypes(raw); err != nil {
204			return nil, err
205		}
206		ctx := &Context{values: make(map[string]string, len(root))}
207		for k, v := range root {
208			// 经过 checkContextValueTypes 后所有值都是字符串；数字（含超出浮点
209			// 范围的 json.Number）、布尔、null、对象、数组都已按所属属性报错。
210			ctx.values[k] = v.(string)
211		}
212		return ctx, nil
213	}
214	
215	// checkContextValueTypes 按文件原文顺序扫描已通过语法与重复字段检查的
216	// context 对象，报告第一个值不是字符串的顶层属性。键名使用解码后的文字
217	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。嵌套
218	// 对象或数组整体跳过，其内部成员不单独检查。
219	func checkContextValueTypes(raw []byte) error {
220		dec := json.NewDecoder(bytes.NewReader(raw))
221		// UseNumber：数字按 json.Number 原样保留而不转 float64，使超出浮点范围
222		// 的合法数字（如 1e400）也能落到“值必须是字符串”的属性类型错误，而不是
223		// 在解码阶段被报成 JSON 语法问题。
224		dec.UseNumber()
225		// 第一个令牌必须是顶层对象的 '{'；非对象的情形在 ParseContext 中报告。
226		if tok, err := dec.Token(); err != nil || tok != json.Delim('{') {
227			return nil
228		}
229		for dec.More() {
230			keyTok, err := dec.Token()
231			if err != nil {
232				return nil // 语法错误留给严格解码的报错
233			}
234			key, _ := keyTok.(string)
235			var value any
236			if err := dec.Decode(&value); err != nil {
237				return nil // 语法错误留给严格解码的报错
238			}
239			if _, ok := value.(string); !ok {
240				return fmt.Errorf("%s: value must be a string", appendFieldPath("context", key))
241			}
242		}
243		return nil
244	}
245	
246	// Get looks up an attribute; an empty string is a legal value.
247	func (c *Context) Get(attribute string) (string, bool) {
248		if c == nil {
249			return "", false
250		}
251		v, ok := c.values[attribute]
252		return v, ok
253	}
254	
255	// Find returns the flag with the given key, or nil if absent.
256	func (c *Config) Find(key string) *Flag {
257		if c == nil {
258			return nil
259		}
260		for i := range c.Flags {
261			if c.Flags[i].Key == key {
262				return &c.Flags[i]
263			}
264		}
265		return nil
266	}
267	
268	// Evaluate deterministically evaluates a flag against a context.
269	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
270	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
271	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
272	func (f *Flag) Evaluate(ctx *Context) EvalResult {
273		if !f.Enabled {
274			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
275		}
276		for i := range f.Rules {
277			rule := &f.Rules[i]
278			if rule.matches(ctx) {
279				id := rule.ID
280				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
281			}
282		}
283		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
284	}
285	
286	func (r *Rule) matches(ctx *Context) bool {
287		for i := range r.Conditions {
288			if !r.Conditions[i].matches(ctx) {
289				return false
290			}
291		}
292		return true
293	}
294	
295	func (c Condition) matches(ctx *Context) bool {
296		v, present := ctx.Get(c.Attribute)
297		if !present {
298			return false
299		}
300		switch c.Op {
301		case "eq":
302			return v == c.strVal
303		case "in":
304			for _, candidate := range c.inVal {
305				if v == candidate {
306					return true
307				}
308			}
309			return false
310		default:
311			// 解析阶段已拒绝未知运算符，防御性处理。
312			return false
313		}
314	}
315	
316	// MarshalResult renders the result as a single compact JSON object.
317	func MarshalResult(r EvalResult) ([]byte, error) {
318		var buf bytes.Buffer
319		enc := json.NewEncoder(&buf)
320		enc.SetEscapeHTML(false)
321		if err := enc.Encode(r); err != nil {
322			return nil, err
323		}
324		return bytes.TrimRight(buf.Bytes(), "\n"), nil
325	}
326	
327	// --- strict parsing helpers -------------------------------------------------
328	
329	// isSimpleFieldName 报告字段名是否走点号连接：以 ASCII 字母或下划线开头，
330	// 其后只能含 ASCII 字母、数字、下划线。其他任何名字（含点号、方括号、空白、
331	// 空名、非 ASCII 字符）都改用方括号包住的 JSON 字符串定位，如
332	// context["user.name"]、context[""]。
333	func isSimpleFieldName(name string) bool {
334		if name == "" {
335			return false
336		}
337		for i := 0; i < len(name); i++ {
338			c := name[i]
339			// 非 ASCII 字节（UTF-8 续字节或首字节）一律不满足“仅 ASCII”的要求。
340			if c >= 0x80 {
341				return false
342			}
343			ok := ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z') || c == '_'
344			if i > 0 {
345				ok = ok || ('0' <= c && c <= '9')
346			}
347			if !ok {
348				return false
349			}
350		}
351		return true
352	}
353	
354	// appendFieldPath 在父位置后接上一个字段：简单字段名用点号连接，其余字段名
355	// 用方括号包住一个 JSON 字符串，引号、反斜杠与控制字符按 JSON 转义显示
356	// （Marshal 对 U+2028/U+2029 也会转义，但普通可见 Unicode 保持原样）。
357	// 名字按 JSON 解码后的文字传入，因此直接字符与合法 \uXXXX 转义得到同一位置。
358	func appendFieldPath(parent, name string) string {
359		if isSimpleFieldName(name) {
360			return parent + "." + name
361		}
362		return parent + "[" + jsonQuote(name) + "]"
363	}
364	
365	// jsonQuote 把字符串渲染为带双引号的 JSON 字符串字面量：引号、反斜杠与控制
366	// 字符按 JSON 转义（U+2028/U+2029 也会转义，避免定位文字被行分隔符拆行），
367	// 其余可见字符（含 <>& 与非 ASCII 文字）保持原样。
368	func jsonQuote(s string) string {
369		var buf bytes.Buffer
370		enc := json.NewEncoder(&buf)
371		enc.SetEscapeHTML(false)
372		if err := enc.Encode(s); err != nil {
373			// 不会发生：string 的 JSON 编码没有失败路径；保留一个确定的退路。
374			return strconv.Quote(s)
375		}
376		return string(bytes.TrimRight(buf.Bytes(), "\n"))
377	}
378	
379	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
380	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
381	type jsonFrame struct {
382		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
383		object bool
384		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
385		// Unicode 遍历不登记字段，保持 nil。
386		keys map[string]struct{}
387		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
388		lastKey string
389		// expectKey 标记对象内下一个字符串是否为字段名。
390		expectKey bool
391		// nextIndex 是数组下一个元素的下标。
392		nextIndex int
393	}
394	
395	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
396	// label 是根容器的位置前缀（"config" 或 "context"）。
397	type jsonPathTracker struct {
398		label string
399		stack []*jsonFrame
400	}
401	
402	func newJSONPathTracker(label string) *jsonPathTracker {
403		return &jsonPathTracker{label: label}
404	}
405	
406	func (t *jsonPathTracker) top() *jsonFrame {
407		return t.stack[len(t.stack)-1]
408	}
409	
410	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值按 appendFieldPath
411	// 规则连接（简单名用点号，其余用方括号 JSON 字符串），数组元素用 [下标]。
412	func (t *jsonPathTracker) childPath() string {
413		top := t.top()
414		if top.object {
415			return appendFieldPath(top.path, top.lastKey)
416		}
417		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
418	}
419	
420	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
421	func (t *jsonPathTracker) beginContainer(object bool) string {
422		path := t.label
423		if len(t.stack) > 0 {
424			path = t.childPath()
425		}
426		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
427		return path
428	}
429	
430	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
431	// 一个已完成的值。
432	func (t *jsonPathTracker) endContainer() {
433		if len(t.stack) > 0 {
434			t.stack = t.stack[:len(t.stack)-1]
435		}
436		t.endValue()
437	}
438	
439	// atKey 报告下一个字符串是否应按对象字段名处理。
440	func (t *jsonPathTracker) atKey() bool {
441		return len(t.stack) > 0 && t.top().object && t.top().expectKey
442	}
443	
444	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
445	// 栈为空时返回根标签。
446	func (t *jsonPathTracker) currentPath() string {
447		if len(t.stack) == 0 {
448			return t.label
449		}
450		return t.top().path
451	}
452	
453	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
454	func (t *jsonPathTracker) valuePath() string {
455		if len(t.stack) == 0 {
456			return t.label
457		}
458		return t.childPath()
459	}
460	
461	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
462	// 数组推进元素下标。
463	func (t *jsonPathTracker) endValue() {
464		if len(t.stack) == 0 {
465			return
466		}
467		top := t.top()
468		if top.object {
469			top.expectKey = true
470		} else {
471			top.nextIndex++
472		}
473	}
474	
475	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
476	// 声明同名字段时返回重复字段错误。
477	func (t *jsonPathTracker) noteKey(name string) error {
478		top := t.top()
479		if top.keys == nil {
480			top.keys = make(map[string]struct{})
481		}
482		if _, dup := top.keys[name]; dup {
483			return fmt.Errorf("%s: duplicate field %s", appendFieldPath(top.path, name), jsonQuote(name))
484		}
485		top.keys[name] = struct{}{}
486		top.lastKey = name
487		top.expectKey = false
488		return nil
489	}
490	
491	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
492	// 仅维护字段值路径所需的状态。
493	func (t *jsonPathTracker) setKey(name string) {
494		top := t.top()
495		top.lastKey = name
496		top.expectKey = false
497	}
498	
499	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
500	// 不覆盖已记录的字段名；语法错误留给后续严格 JSON 解码报告。
501	func (t *jsonPathTracker) noteInvalidKey() {
502		t.top().expectKey = false
503	}
504	
505	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
506	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
507	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
508	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
509	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
510	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
511	// 留给严格 JSON 解码。
512	func rejectDuplicateFields(raw []byte, label string) error {
513		dec := json.NewDecoder(bytes.NewReader(raw))
514		// UseNumber：数字以 json.Number 令牌返回而不转 float64，否则超出浮点范围
515		// 的合法数字（如 1e400）会让令牌流提前报错并中止，遮住其后的重复字段。
516		dec.UseNumber()
517		tracker := newJSONPathTracker(label)
518		for {
519			tok, err := dec.Token()
520			if err != nil {
521				// io.EOF 或语法错误；语法错误由后续严格 JSON 解码报告。
522				break
523			}
524			switch t := tok.(type) {
525			case json.Delim:
526				switch t {
527				case '{':
528					tracker.beginContainer(true)
529				case '[':
530					tracker.beginContainer(false)
531				case '}', ']':
532					tracker.endContainer()
533				}
534			case string:
535				if tracker.atKey() {
536					if err := tracker.noteKey(t); err != nil {
537						return err
538					}
539				} else {
540					tracker.endValue()
541				}
542			default:
543				tracker.endValue()
544			}
545		}
546		return nil
547	}
548	
549	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
550	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
551	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
552	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
553	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
554	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
555	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
556	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
557	// Unmarshal。
558	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
559		tracker := newJSONPathTracker(label)
560		i := 0
561		for i < len(raw) {
562			c := raw[i]
563			switch {
564			case c == '{' || c == '[':
565				tracker.beginContainer(c == '{')
566				i++
567			case c == '}' || c == ']':
568				tracker.endContainer()
569				i++
570			case c == '"':
571				end := jsonStringEnd(raw, i)
572				contentEnd := end
573				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
574					contentEnd-- // 去掉右引号；未终止的字符串留给严格 JSON 解码报告
575				}
576				content := raw[i+1 : contentEnd]
577				if tracker.atKey() {
578					if bad := findBadUnicodeEscape(content); bad != nil {
579						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
580							tracker.currentPath(), string(content), bad.escape, bad.detail)
581					}
582					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给严格 JSON 解码。
583					if name, ok := decodeJSONString(raw[i:end]); ok {
584						tracker.setKey(name)
585					} else {
586						tracker.noteInvalidKey()
587					}
588				} else {
589					path := tracker.valuePath()
590					if bad := findBadUnicodeEscape(content); bad != nil {
591						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
592							path, bad.escape, bad.detail)
593					}
594					tracker.endValue()
595				}
596				i = end
597			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
598				i++
599			default:
600				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
601				for i < len(raw) && !isJSONStructural(raw[i]) {
602					i++
603				}
604				tracker.endValue()
605			}
606		}
607		return nil
608	}
609	
610	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
611	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
612	func decodeJSONString(lit []byte) (s string, ok bool) {
613		if err := json.Unmarshal(lit, &s); err != nil {
614			return "", false
615		}
616		return s, true
617	}
618	
619	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
620	type badEscape struct {
621		escape string // 原文中的转义序列，如 \uD800
622		detail string // 具体问题（孤立高代理项/孤立低代理项）
623	}
624	
625	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
626	// （右引号之后的下标）；未终止时返回 len(raw)。
627	func jsonStringEnd(raw []byte, i int) int {
628		j := i + 1
629		for j < len(raw) {
630			switch raw[j] {
631			case '\\':
632				j += 2
633			case '"':
634				return j + 1
635			default:
636				j++
637			}
638		}
639		return len(raw)
640	}
641	
642	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
643	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
644	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
645	// 语法错误，不在此报告。
646	func findBadUnicodeEscape(content []byte) *badEscape {
647		j := 0
648		for j < len(content) {
649			if content[j] != '\\' {
650				j++
651				continue
652			}
653			if j+1 >= len(content) {
654				break
655			}
656			if content[j+1] != 'u' {
657				j += 2
658				continue
659			}
660			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
661				j += 2
662				continue
663			}
664			cp := hexVal4(content[j+2 : j+6])
665			switch {
666			case cp >= 0xD800 && cp <= 0xDBFF:
667				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
668				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
669					isHex4(content[j+8:j+12]) {
670					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
671						j += 12
672						continue
673					}
674				}
675				return &badEscape{
676					escape: string(content[j : j+6]),
677					detail: "high surrogate is not followed by a low surrogate",
678				}
679			case cp >= 0xDC00 && cp <= 0xDFFF:
680				return &badEscape{
681					escape: string(content[j : j+6]),
682					detail: "low surrogate is not preceded by a high surrogate",
683				}
684			}
685			j += 6
686		}
687		return nil
688	}
689	
690	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
691	func isJSONStructural(b byte) bool {
692		switch b {
693		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
694			return true
695		}
696		return false
697	}
698	
699	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
700	func isHex4(b []byte) bool {
701		if len(b) != 4 {
702			return false
703		}
704		for _, c := range b {
705			if !isHexDigit(c) {
706				return false
707			}
708		}
709		return true
710	}
711	
712	func isHexDigit(c byte) bool {
713		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
714	}
715	
716	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
717	func hexVal4(b []byte) int {
718		v := 0
719		for _, c := range b {
720			v <<= 4
721			switch {
722			case '0' <= c && c <= '9':
723				v |= int(c - '0')
724			case 'a' <= c && c <= 'f':
725				v |= int(c-'a') + 10
726			default: // 'A' <= c && c <= 'F'
727				v |= int(c-'A') + 10
728			}
729		}
730		return v
731	}
732	
733	func parseFlag(raw any, index int) (Flag, error) {
734		loc := fmt.Sprintf("config.flags[%d]", index)
735		obj, ok := raw.(map[string]any)
736		if !ok {
737			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
738		}
739		key, err := requireNonEmptyString(obj, "key", loc)
740		if err != nil {
741			return Flag{}, err
742		}
743		enabled, err := requireBool(obj, "enabled", loc)
744		if err != nil {
745			return Flag{}, err
746		}
747		def, err := requireBool(obj, "default", loc)
748		if err != nil {
749			return Flag{}, err
750		}
751		rulesArr, err := requireArrayField(obj, "rules", loc)
752		if err != nil {
753			return Flag{}, err
754		}
755		flag := Flag{Key: key, Enabled: enabled, Default: def}
756		seenRules := map[string]int{}
757		for ri, rv := range rulesArr {
758			rule, err := parseRule(rv, index, ri)
759			if err != nil {
760				return Flag{}, err
761			}
762			if prev, dup := seenRules[rule.ID]; dup {
763				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
764			}
765			seenRules[rule.ID] = ri
766			flag.Rules = append(flag.Rules, rule)
767		}
768		return flag, nil
769	}
770	
771	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
772		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
773		obj, ok := raw.(map[string]any)
774		if !ok {
775			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
776		}
777		id, err := requireNonEmptyString(obj, "id", loc)
778		if err != nil {
779			return Rule{}, err
780		}
781		value, err := requireBool(obj, "value", loc)
782		if err != nil {
783			return Rule{}, err
784		}
785		condsArr, err := requireArrayField(obj, "conditions", loc)
786		if err != nil {
787			return Rule{}, err
788		}
789		if len(condsArr) == 0 {
790			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
791		}
792		rule := Rule{ID: id, Value: value}
793		for ci, cv := range condsArr {
794			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
795			if err != nil {
796				return Rule{}, err
797			}
798			rule.Conditions = append(rule.Conditions, cond)
799		}
800		return rule, nil
801	}
802	
803	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
804		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
805		obj, ok := raw.(map[string]any)
806		if !ok {
807			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
808		}
809		attribute, err := requireNonEmptyString(obj, "attribute", loc)
810		if err != nil {
811			return Condition{}, err
812		}
813		op, err := requireNonEmptyString(obj, "op", loc)
814		if err != nil {
815			return Condition{}, err
816		}
817		valueField, err := requireField(obj, "value", loc)
818		if err != nil {
819			return Condition{}, err
820		}
821		cond := Condition{Attribute: attribute, Op: op}
822		switch op {
823		case "eq":
824			s, ok := valueField.(string)
825			if !ok {
826				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
827			}
828			cond.strVal = s
829		case "in":
830			arr, ok := valueField.([]any)
831			if !ok {
832				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
833			}
834			if len(arr) == 0 {
835				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
836			}
837			for ii, item := range arr {
838				s, ok := item.(string)
839				if !ok {
840					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
841				}
842				cond.inVal = append(cond.inVal, s)
843			}
844		default:
845			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
846		}
847		return cond, nil
848	}
849	
850	func requireField(obj map[string]any, name, loc string) (any, error) {
851		v, ok := obj[name]
852		if !ok {
853			return nil, fmt.Errorf("%s: field is required", appendFieldPath(loc, name))
854		}
855		if v == nil {
856			return nil, fmt.Errorf("%s: must not be null", appendFieldPath(loc, name))
857		}
858		return v, nil
859	}
860	
861	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
862		v, err := requireField(obj, name, loc)
863		if err != nil {
864			return nil, err
865		}
866		arr, ok := v.([]any)
867		if !ok {
868			return nil, fmt.Errorf("%s: must be an array", appendFieldPath(loc, name))
869		}
870		return arr, nil
871	}
872	
873	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
874		v, err := requireField(obj, name, loc)
875		if err != nil {
876			return "", err
877		}
878		s, ok := v.(string)
879		if !ok {
880			return "", fmt.Errorf("%s: must be a string", appendFieldPath(loc, name))
881		}
882		if s == "" {
883			return "", fmt.Errorf("%s: must not be empty", appendFieldPath(loc, name))
884		}
885		return s, nil
886	}
887	
888	func requireBool(obj map[string]any, name, loc string) (bool, error) {
889		v, err := requireField(obj, name, loc)
890		if err != nil {
891			return false, err
892		}
893		b, ok := v.(bool)
894		if !ok {
895			return false, fmt.Errorf("%s: must be a boolean", appendFieldPath(loc, name))
896		}
897		return b, nil
898	}
