435		// 字段位置统一规则：简单字段名（ASCII 字母/下划线开头，仅含 ASCII 字母数字
436		// 下划线）继续用点号；其他名字在父位置后用方括号包住一个 JSON 字符串。
437		for _, tc := range []struct {
438			name string
439			raw  string
440			want string
441		}{
442			{"dotted name is bracketed", `{"user.name":7}`, `context["user.name"]`},
443			{"empty name is bracketed", `{"":7}`, `context[""]`},
444			{"newline in name is json escaped", "{\"a\\nb\":7}", `context["a\nb"]`},
445			{"tab in name is json escaped", "{\"a\\tb\":7}", `context["a\tb"]`},
446			{"quote in name is json escaped", `{"a\"b":7}`, `context["a\"b"]`},
447			{"backslash in name is json escaped", `{"a\\b":7}`, `context["a\\b"]`},
448			{"brackets are not array indices", `{"names[0]":7}`, `context["names[0]"]`},
449			{"leading digit is bracketed", `{"0ab":7}`, `context["0ab"]`},
450			{"dash is bracketed", `{"a-b":7}`, `context["a-b"]`},
451			{"simple underscore stays dotted", `{"_":7}`, `context._`},
452			{"simple alnum stays dotted", `{"plan_2":7}`, `context.plan_2`},
453		} {
454			t.Run(tc.name, func(t *testing.T) {
455				_, err := ParseContext([]byte(tc.raw))
456				if err == nil {
457					t.Fatalf("expected type error, got nil")
458				}
459				if !strings.Contains(err.Error(), tc.want) ||
460					!strings.Contains(err.Error(), "value must be a string") {
461					t.Fatalf("err=%q want location %q", err.Error(), tc.want)
462				}
463				// 控制字符必须转义显示：定位文字本身不能被拆成多行。
464				if strings.Contains(strings.SplitN(err.Error(), ": ", 2)[0], "\n") {
465					t.Fatalf("location text must stay on one line: %q", err.Error())
466				}
467			})
468		}
469	
470		// 合法 Unicode 转义先解码再定位：. 与直接写出的点号得到同一位置。
471		_, err := ParseContext([]byte(`{"user.name":7}`))
472		if err == nil || !strings.Contains(err.Error(), `context["user.name"]`) {
473			t.Fatalf("escaped dot key: err=%v", err)
474		}
475	
476		// 重复字段同样按统一规则定位；名字渲染为 JSON 字符串。
477		_, err = ParseContext([]byte(`{"user.name":1,"user.name":2}`))
478		if err == nil || !strings.Contains(err.Error(), `context["user.name"]: duplicate field "user.name"`) {
479			t.Fatalf("duplicate dotted key: err=%v", err)
480		}
481		// 转义形式与直接字符是同名字段：重复检查与定位都按解码后的文字。
482		_, err = ParseContext([]byte(`{"x.y":1,"x.y":2}`))
483		if err == nil || !strings.Contains(err.Error(), `context["x.y"]: duplicate field "x.y"`) {
484			t.Fatalf("duplicate escaped key: err=%v", err)
485		}
486		_, err = ParseContext([]byte(`{"":1,"":2}`))
487		if err == nil || !strings.Contains(err.Error(), `context[""]: duplicate field ""`) {
488			t.Fatalf("duplicate empty key: err=%v", err)
489		}
490	
491		// 配置附加字段名为 meta.info，其中嵌套对象的 owner 重复：
492		// 应显示 config.flags[0]["meta.info"].owner。
493		rawConfig := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
494			"meta.info":{"owner":"a","owner":"b"}}]}`
495		_, err = ParseConfig([]byte(rawConfig))
496		if err == nil || !strings.Contains(err.Error(), `config.flags[0]["meta.info"].owner`) ||
497			!strings.Contains(err.Error(), "duplicate field") {
498			t.Fatalf("nested duplicate under dotted extra field: err=%v", err)
499		}
500		// 附加字段数组元素里的点号字段名同样加方括号。
501		rawConfig = `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
502			"tags":[{"v":1},{"a.b":1,"a.b":2}]}]}`
503		_, err = ParseConfig([]byte(rawConfig))
504		if err == nil || !strings.Contains(err.Error(), `config.flags[0].tags[1]["a.b"]`) ||
505			!strings.Contains(err.Error(), "duplicate field") {
506			t.Fatalf("duplicate in extra array element: err=%v", err)
507		}
508		// 顶层附加的点号字段名。
509		_, err = ParseConfig([]byte(`{"flags":[],"x.y":1,"x.y":2}`))
510		if err == nil || !strings.Contains(err.Error(), `config["x.y"]: duplicate field "x.y"`) {
511			t.Fatalf("duplicate dotted top-level extra field: err=%v", err)
512		}
513	
514		// 点号字段名的值含不完整 Unicode 转义：错误位置用方括号包住字段名。
515		_, err = ParseContext([]byte(`{"user.name":"\uD800"}`))
516		if err == nil || !strings.Contains(err.Error(), `context["user.name"]`) ||
517			!strings.Contains(err.Error(), "does not form a complete character") {
518			t.Fatalf("bad escape under dotted key: err=%v", err)
519		}
520	}
