551			"meta":{"o\uD800wner":1}}]}`))
552		if err == nil || !strings.Contains(err.Error(), `config.flags[0].meta`) ||
553			!strings.Contains(err.Error(), `\uD800`) {
554			t.Fatalf("bad field name in nested object: err=%v", err)
555		}
556	
557		// 数组元素对象内的字段名含坏转义：位置指向该元素对象。
558		_, err = ParseConfig([]byte(`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
559			"tags":[{"k\uDC00":1}]}]}`))
560		if err == nil || !strings.Contains(err.Error(), `config.flags[0].tags[0]`) ||
