605	func TestContextOutOfRangeNumbersAreTypeErrors(t *testing.T) {
606		// 1 后接 400 个 0：远超 float64 可表示范围的合法 JSON 整数。它与 1e400、
607		// -1e400 一样是语法合法的 JSON 数字——用户把应为字符串的属性写成数字时，
608		// 必须报该属性的类型错误，而不是被解码阶段当成 JSON 语法错误。
609		hugeInt := "1" + strings.Repeat("0", 400)
610		cases := []struct {
611			name         string
612			raw          string
613			wantAttr     string
614			topLevelOnly bool // 对象/数组值的错误不得指向内部成员
615		}{
616			{"exponent overflow", `{"plan":1e400}`, "context.plan", false},
617			{"negative exponent overflow", `{"plan":-1e400}`, "context.plan", false},
618			{"400-digit integer", `{"plan":` + hugeInt + `}`, "context.plan", false},
619			{"object holding big number", `{"plan":{"inner":1e400}}`, "context.plan", true},
620			{"array holding big numbers", `{"plan":[1e400,-1e400]}`, "context.plan", true},
621			{"nested object then later scalar", `{"a":"x","obj":{"inner":` + hugeInt + `},"b":2}`, "context.obj", true},
622		}
623		for _, tc := range cases {
624			t.Run(tc.name, func(t *testing.T) {
625				_, err := ParseContext([]byte(tc.raw))
