627					t.Fatalf("ParseContext(%s): expected error, got nil", tc.raw)
628				}
629				msg := err.Error()
630				if strings.Contains(msg, "invalid JSON") {
631					t.Fatalf("a legal big number must not be reported as a JSON syntax error: %q", msg)
632				}
633				if !strings.Contains(msg, tc.wantAttr) || !strings.Contains(msg, "value must be a string") {
634					t.Fatalf("err=%q, want %s string-type error", msg, tc.wantAttr)
635				}
636				if tc.topLevelOnly && strings.Contains(msg, "inner") {
637					t.Fatalf("object/array value error must stay on the top-level attribute: %q", msg)
638				}
639			})
640		}
641	
642		// 规则不引用该属性：上下文校验独立于配置与求值，同样拒绝并按属性类型错误报告。
643		_, err := ParseContext([]byte(`{"unreferenced":1e400}`))
644		if err == nil || !strings.Contains(err.Error(), "context.unreferenced") ||
645			!strings.Contains(err.Error(), "value must be a string") ||
