721	func TestQuotedBigNumberStaysString(t *testing.T) {
722		hugeInt := "1" + strings.Repeat("0", 400)
723		// 同样的数字文本加上引号后就是普通字符串，按原文参与 eq 匹配，
724		// 不能被数值化、改写或继续拒绝。
725		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
726			{"id":"r-exp","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"1e400"}]},
727			{"id":"r-neg","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"-1e400"}]},
728			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
729		for _, tc := range []struct {
730			ctxRaw string
731			ruleID string
732			reason EvalReason
733		}{
734			{`{"plan":"1e400"}`, "r-exp", EvalRule},
735			{`{"plan":"-1e400"}`, "r-neg", EvalRule},
736			{`{"plan":"` + hugeInt + `"}`, "r-int", EvalRule},
737			{`{"plan":"1e401"}`, "", EvalDefault}, // 不做数值换算："1e401" != "1e400"
738		} {
739			got := eval(t, cfg, "f", tc.ctxRaw)
740			if got.Reason != tc.reason ||
741				(tc.reason == EvalRule && (got.RuleID == nil || *got.RuleID != tc.ruleID)) {
742				t.Fatalf("ctx=%s: got %+v, want reason=%s rule=%s", tc.ctxRaw, got, tc.reason, tc.ruleID)
743			}
744		}
745	
746		// 1e400 与 1 后接 400 个 0 在数值上相等，但字符串写法不同：不得互相命中。
747		cfgInt := `{"flags":[{"key":"g","enabled":true,"default":false,"rules":[
748			{"id":"r-int","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"` + hugeInt + `"}]}]}]}`
749		if got := eval(t, cfgInt, "g", `{"plan":"1e400"}`); got.Reason != EvalDefault {
750			t.Fatalf("numerically equal spellings must not match as strings: %+v", got)
751		}
752		if got := eval(t, cfgInt, "g", `{"plan":"`+hugeInt+`"}`); got.Reason != EvalRule {
753			t.Fatalf("identical spelling must match verbatim: %+v", got)
754		}
755	
756		// ParseContext 保留引号内的原文，不做任何转换。
757		ctx := mustParseContext(t, `{"plan":"1e400"}`)
758		if v, ok := ctx.Get("plan"); !ok || v != "1e400" {
759			t.Fatalf("quoted big number was rewritten: %q %v", v, ok)
760		}
761	}
