				t.Fatalf("error = %q, want %q wording", err.Error(), "duplicate field")
			}
			if !strings.Contains(err.Error(), tc.want) {
				t.Fatalf("error = %q, want location %q", err.Error(), tc.want)
			}
		})
	}
}

